import { z } from "zod";
const categoriaSchema = z.object({
  nome: z.string().min(1, "Descrição é obrigatória")
});
const vendaSchema = z.object({
  clienteId: z.string().min(1, "Cliente é obrigatório").optional(),
  metodoPagamento: z.string().min(1, "Método de pagamento é obrigatório"),
  observacao: z.string().optional(),
  itens: z.array(
    z.object({
      produtoId: z.string().min(1, "Produto é obrigatório"),
      quantidade: z.number().min(1, "Quantidade deve ser maior que 0"),
      precoUnitario: z.number().min(0, "Preço unitário deve ser maior ou igual a 0"),
      desconto: z.number().min(0, "Desconto deve ser maior ou igual a 0").default(0),
      descontoPercentual: z.number().min(0, "Desconto deve ser maior ou igual a 0").default(0),
      total: z.number().min(0, "Total deve ser maior ou igual a 0")
    })
  ).min(1, "Venda deve ter pelo menos um item"),
  subtotal: z.number().min(0),
  desconto: z.number().min(0).default(0),
  total: z.number().min(0),
  status: z.string().default("FINALIZADA")
});
export {
  categoriaSchema as c,
  vendaSchema as v
};
